            .git_stdout(&["show", "-s", "--no-show-signature", "--format=%B", commit.as_str()])?
            .into_text();
        let trailer = |key: &str| {
            message
                .lines()
                .find_map(|line| line.strip_prefix(key)?.strip_prefix(": "))
                .unwrap_or_default()
                .to_string()
        };
