    ///
    /// [`VcsError::CheckpointHeld`] when `name` already exists, so two runs never share one; a failed git command
    /// otherwise.
    pub fn create_checkpoint(&self, name: &str, facts: &CheckpointFacts, date: &str) -> Result<CommitSha, VcsError> {
        let git_dir = self.git_stdout(&["rev-parse", "--absolute-git-dir"])?.path();
        let index = git_dir.join("callisto-checkpoint.index");
        let index_str = index.to_string_lossy().into_owned();
        let env = [("GIT_INDEX_FILE", index_str.as_str())];
        let real_index = self
            .root()
            .join(self.git_stdout(&["rev-parse", "--git-path", "index"])?.path());
        let created = (|| {
            let index_commit =
                self.internal_commit(self.git_stdout(&["write-tree"])?.line(), &[&facts.head], "index")?;
