/// Stages `paths` (relative to this root) in the index, each matched literally. Writes the index, so it requires an
/// [`ApplyPermit`].
pub fn stage(&self, paths: &[GitPath<'_>], permit: &ApplyPermit) -> Result<(), VcsError> {
    self.index_command(&["add", "--"], paths, permit)
}

/// Stages the removal of `paths` from the index, leaving the files on disk; a path the index does not hold is
/// skipped. Writes the index, so it requires an [`ApplyPermit`].
pub fn stage_removal(&self, paths: &[GitPath<'_>], permit: &ApplyPermit) -> Result<(), VcsError> {
    self.index_command(&["rm", "--cached", "--ignore-unmatch", "--"], paths, permit)
}

fn index_command(&self, prefix: &[&str], paths: &[GitPath<'_>], _permit: &ApplyPermit) -> Result<(), VcsError> {
    let specs: Vec<Pathspec> = paths.iter().map(|path| path.pathspec()).collect();
    let mut args = prefix.to_vec();
    args.extend(specs.iter().map(Pathspec::as_str));
    let output = self.runner.run("git", &args, &self.root)?;
    if !output.success() {
        return Err(VcsError::Command(CommandError::Failed {
            program: "git".to_string(),
            exit_code: output.exit_code,
            stderr: output.redacted_stderr(),
        }));
    }
    Ok(())
}

