use std::path::PathBuf;

use crate::{CommandError, CommitRecord, CommitWalkError, CommitWalker};
use thiserror::Error;

pub mod access;
mod boundary;
pub mod checkpoint;
mod remote;

pub use access::{FirstParentTouches, GitAccess};
pub use boundary::{GitPath, GitStdout, LogEntry, Pathspec, Rev};
pub use checkpoint::{Checkpoint, CheckpointFacts, VERSION_CHECKPOINT};
pub use remote::{GitRemote, RemoteTag};

/// The environment a command runner gives every `git` child: a credential prompt fails instead of waiting for input
/// that never comes, and the messages Callisto matches stay in git's untranslated English.
pub const GIT_ENVIRONMENT: [(&str, &str); 2] = [("GIT_TERMINAL_PROMPT", "0"), ("LC_ALL", "C")];

#[derive(Clone, Debug, Error, miette::Diagnostic, PartialEq, Eq)]
#[non_exhaustive]
pub enum VcsError {
    #[error("git error: {0}")]
    #[diagnostic(
        code(E051),
        help("Inspect the reported Git failure and its context; no more specific fix is known.")
    )]
    Git(String),

    #[error("release trust requires a SHA-1 Git object format; found `{found}`")]
    #[diagnostic(
        code(E265),
        help("Run release trust checks against a repository using the SHA-1 object format.")
    )]
    UnsupportedObjectFormat { found: String },

    #[error("release trust requires a complete, non-shallow Git repository")]
    #[diagnostic(code(E266), help("Fetch full history with `git fetch --unshallow` before retrying."))]
    ShallowRepository,

    #[error("commit-based version inference needs the full Git history, but this repository is a shallow clone")]
    #[diagnostic(
        code(E315),
        help(
            "Fetch the full history (`git fetch --unshallow`, or `fetch-depth: 0` for actions/checkout), or give the \
             packages that need no commit inference `release-trigger = \"changeset\"`."
        )
    )]
    ShallowHistory,

    #[error("release trust requires a clean worktree; found `{path}`")]
    #[diagnostic(
        code(E267),
        help("Commit, stash, or remove the listed tracked or untracked change before retrying.")
    )]
    DirtyWorktree { path: String },

    #[error("another `callisto version` run holds the checkpoint `{name}`")]
    #[diagnostic(
        code(E341),
        help("Wait for the other run to finish, then run `callisto version` again to resume or finish its work.")
    )]
    CheckpointHeld { name: String },

    #[error("reference `{ref_name}` was not found")]
    #[diagnostic(code(E052), help("Check if reference or tag exists in local or remote Git refs."))]
    RefNotFound { ref_name: String },

    #[error("tag glob pattern `{pattern}` is not a valid glob: {message}")]
    #[diagnostic(
        code(E053),
        help("Fix the glob syntax (e.g. balance `{{`/`}}` and `[`/`]`) or use a literal tag name.")
    )]
    InvalidGlob { pattern: String, message: String },

    #[error("staged content for `{path}` no longer matches the index (worktree bytes hash to a different blob than the staged `{expected_sha}`)")]
    #[diagnostic(
        code(E059),
        help("Re-stage the file with `git add` so the worktree matches the index, or read it again after staging.")
    )]
    StagedContentMismatch { path: String, expected_sha: String },

    #[error("could not parse `git diff --raw -z` output: {detail}")]
    #[diagnostic(
        code(E300),
        help("Retry; a `git diff` invocation returning output in this shape suggests a Git version mismatch.")
    )]
    MalformedDiffOutput { detail: String },

    #[error("could not parse `git log` output into commit records: {detail}")]
    #[diagnostic(
        code(E301),
        help("Retry; a `git log` invocation returning output in this shape suggests a Git version mismatch.")
    )]
    MalformedLogOutput { detail: String },

    #[error("Git returned an invalid commit SHA {context}: {message}")]
    #[diagnostic(
        code(E302),
        help("Retry; Git returning a commit reference in this shape suggests a Git version mismatch.")
    )]
    InvalidCommitSha { context: String, message: String },

    #[error("could not resolve the Git repository root: {detail}")]
    #[diagnostic(
        code(E303),
        help("Ensure the repository's toplevel directory exists and is readable.")
    )]
    InvalidRepositoryRoot { detail: String },

    /// The `git` binary itself could not be run. `transparent` so callers
    /// can match the underlying [`CommandError`] through it.
    #[error(transparent)]
    #[diagnostic(transparent)]
    Command(#[from] CommandError),
}

/// Narrows a [`VcsError`] to the Layer 1 [`CommitWalkError`] vocabulary at
/// the [`CommitWalker`] boundary.
///
/// [`CommitWalkError::Command`] and [`CommitWalkError::RefNotFound`] survive
/// as themselves -- they are the two distinctions consumers branch on. Every
/// other variant has no Layer 1 equivalent, so it collapses into [`CommitWalkError::Backend`] carrying this error's
/// own `Display` rendering; nothing is lost from the message a user sees.
impl From<VcsError> for CommitWalkError {
    fn from(err: VcsError) -> Self {
        match err {
            VcsError::Command(inner) => CommitWalkError::Command(inner),
            VcsError::RefNotFound { ref_name } => CommitWalkError::RefNotFound { ref_name },
            other => CommitWalkError::Backend {
                message: other.to_string(),
            },
        }
    }
}

/// A commit as produced by a history walk.
///
/// Aliases [`crate::CommitRecord`] rather than redeclaring it, so a
/// walk's output crosses the [`CommitWalker`] seam without a conversion and
/// there is exactly one definition of a commit's shape in the workspace.
pub type GitCommit = CommitRecord;

/// Compiles `pattern` into a [`globset::GlobMatcher`], surfacing a malformed
/// pattern as [`VcsError::InvalidGlob`] rather than letting it silently
/// disable filtering -- which would match every tag, a real correctness
/// risk for release tagging (a malformed tag template could make "last tag"
/// resolution pick an unrelated package's tag). Shared by
/// [`GitAccess::list_tags`] and `callisto-graph`'s `tags::matching_tags`, so
/// both filter tag names with identical semantics.
pub fn compile_tag_glob(pattern: &str) -> Result<globset::GlobMatcher, VcsError> {
    globset::Glob::new(pattern)
        .map(|g| g.compile_matcher())
        .map_err(|e| VcsError::InvalidGlob {
            pattern: pattern.to_string(),
            message: e.to_string(),
        })
}

/// Whether [`GitAccess::create_tag`] lets the ambient Git signing
/// configuration (`tag.gpgSign`/`commit.gpgsign`) apply, or forces an
/// unsigned tag regardless of it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TagSignPolicy {
    /// Let the repository's own Git config decide -- the right default for
    /// a human-run tag.
    RespectRepoConfig,
    /// Always pass `--no-sign`, regardless of `tag.gpgSign`/`commit.gpgsign`.
    /// Some CI contexts set those globally (for commit signing) with no
    /// tag-signing key available; the durable release executor uses this to
    /// avoid failing there.
    ForceUnsigned,
}

