//! The Git boundary: revisions go in only as [`Rev`], paths only as [`GitPath`] and the [`Pathspec`] it renders, and a
//! command's stdout comes out only through [`GitStdout`], read in the framing that command prints.

use std::fmt;
use std::path::{Path, PathBuf};

use super::VcsError;
use crate::tag::is_legal_ref_name;
use crate::{CommandOutput, CommitSha};

/// A revision argument. It is built only from a commit id, `HEAD`, or a fully qualified `refs/tags/<name>` or
/// `refs/heads/<name>` whose name holds no revision syntax, so what Git is asked to resolve is exactly what was meant.
///
/// A command takes it after `--end-of-options`, so it is never read as a flag either.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct Rev(String);

impl Rev {
    pub fn head() -> Self {
        Self("HEAD".to_owned())
    }

    /// The tag `name`; `None` when no tag can be called that (`a^` or `a@{1}` would be read as revision syntax).
    pub fn tag(name: &str) -> Option<Self> {
        is_legal_ref_name(name).then(|| Self(format!("refs/tags/{name}")))
    }

    /// The branch `name`; `None` when no branch can be called that.
    pub fn branch(name: &str) -> Option<Self> {
        is_legal_ref_name(name).then(|| Self(format!("refs/heads/{name}")))
    }

    /// A ref Callisto itself names, which holds no revision syntax.
    pub(super) fn own_ref(name: &'static str) -> Self {
        debug_assert!(is_legal_ref_name(name), "`{name}` is not a legal ref name");
        Self(name.to_owned())
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl From<&CommitSha> for Rev {
    fn from(sha: &CommitSha) -> Self {
        Self(sha.as_str().to_owned())
    }
}

impl fmt::Display for Rev {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

/// A literal path, the only way a path reaches a Git command. Each command spells a path its own way, and the spelling
/// lives here: no spelling reads the path as a glob, a revision or magic.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct GitPath<'a>(&'a Path);

impl<'a> GitPath<'a> {
    pub fn new(path: &'a Path) -> Self {
        Self(path)
    }

    /// For commands that take pathspecs (`add`, `rm`, `diff`, `log`, `ls-files`): matched literally, so a directory
    /// named with `*` or `?` selects only itself.
    pub fn pathspec(self) -> Pathspec {
        Pathspec(format!(":(literal){}", self.0.to_string_lossy()))
    }

    /// For pathspec commands: everything except this path, matched literally.
    pub fn excluded(self) -> Pathspec {
        Pathspec(format!(":(exclude,literal){}", self.0.to_string_lossy()))
    }

    /// For `git check-ignore`, which rejects `:(literal)`: a relative path gets a `./` prefix, which keeps a leading `:`
    /// from being read as pathspec magic.
    pub fn check_ignore(self) -> String {
        if self.0.is_absolute() {
            self.0.to_string_lossy().into_owned()
        } else {
            format!("./{}", self.0.to_string_lossy())
        }
    }

    /// For commands that name an object as `<rev>:<path>`, relative to the directory they run in.
    pub fn at(self, rev: &Rev) -> String {
        format!("{rev}:./{}", self.0.to_string_lossy())
    }
}

/// A pathspec argument. There is no constructor from raw text, so a path cannot be matched as a glob or magic word.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Pathspec(String);

impl Pathspec {
    /// Every file named `file_name`, at any depth; the name itself is matched literally.
    pub fn named_anywhere(file_name: &str) -> Self {
        let mut spec = String::from(":(glob)**/");
        for c in file_name.chars() {
            if matches!(c, '*' | '?' | '[' | '\\') {
                spec.push('\\');
            }
            spec.push(c);
        }
        Self(spec)
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

/// What a Git command that exited 0 printed.
#[derive(Debug)]
pub struct GitStdout(String);

impl GitStdout {
    /// The stdout of a successful command; a failed one is handed back for the caller's own error.
    pub fn of(output: CommandOutput) -> Result<Self, CommandOutput> {
        if output.success() {
            Ok(Self(output.stdout))
        } else {
            Err(output)
        }
    }

    /// A one-line answer, such as an object id or a ref, without its line terminator.
    pub fn line(&self) -> &str {
        self.0.strip_suffix('\n').unwrap_or(&self.0)
    }

    /// One item per line, for items that cannot hold a newline, such as object ids and ref names.
    pub fn lines(&self) -> impl Iterator<Item = &str> {
        self.0.lines()
    }

    /// A path printed on its own line: its own text, whitespace included, with only the line terminator removed.
    pub fn path(&self) -> PathBuf {
        PathBuf::from(self.line())
    }

    /// Everything printed, such as a file's contents from `git show <rev>:<path>`.
    pub fn into_text(self) -> String {
        self.0
    }

    /// `-z` output: each NUL-terminated field, never quoted.
    pub fn fields(&self) -> impl Iterator<Item = &str> {
        let fields = self.0.strip_suffix('\0').unwrap_or(&self.0);
        (!fields.is_empty()).then(|| fields.split('\0')).into_iter().flatten()
    }

    /// `git log -z --name-only` run with [`LogEntry::format`]: each commit's header fields and the files it lists.
    pub fn log_entries(&self) -> Result<Vec<LogEntry<'_>>, VcsError> {
        let malformed = |detail: String| VcsError::MalformedLogOutput { detail };
        let mut fields = self.fields().peekable();
        let mut entries = Vec::new();
        while let Some(opener) = fields.next() {
            if !opener.is_empty() {
                return Err(malformed(format!("expected a commit to open with NUL, got {opener:?}")));
            }
            let header = fields
                .next()
                .ok_or_else(|| malformed("expected a header field after the opening NUL".to_owned()))?;
            let mut files = Vec::new();
            while let Some(file) = fields.next_if(|file| !file.is_empty()) {
                // Git puts a newline between the header and the first file.
                files.push(if files.is_empty() {
                    file.strip_prefix('\n').unwrap_or(file)
                } else {
                    file
                });
            }
            entries.push(LogEntry { header, files });
        }
        Ok(entries)
    }
}

/// One commit of [`GitStdout::log_entries`].
#[derive(Debug, PartialEq, Eq)]
pub struct LogEntry<'a> {
    pub header: &'a str,
    pub files: Vec<&'a str>,
}

impl LogEntry<'_> {
    /// The `--format` argument whose output [`GitStdout::log_entries`] reads: each commit opens with NUL, which no
    /// header field or file name can hold, followed by the `placeholder`.
    pub fn format(placeholder: &str) -> String {
        format!("--format=%x00{placeholder}")
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn stdout(text: &str) -> GitStdout {
        GitStdout(text.to_owned())
    }

    #[test]
    fn a_failed_command_has_no_stdout_to_read() {
        let failed = CommandOutput {
            exit_code: Some(1),
            stdout: "x\n".to_owned(),
            stderr: String::new(),
        };
        assert_eq!(GitStdout::of(failed.clone()).unwrap_err(), failed);
    }

    #[test]
    fn a_path_keeps_its_own_whitespace() {
        assert_eq!(stdout(" sub dir /\n").path(), PathBuf::from(" sub dir /"));
        assert_eq!(stdout("abc\n\n").line(), "abc\n");
    }

    #[test]
    fn nul_fields_are_split_on_their_terminator_only() {
        assert_eq!(stdout("a b\0\nc\0").fields().collect::<Vec<_>>(), ["a b", "\nc"]);
        assert_eq!(stdout("").fields().count(), 0);
    }

