    commit_file(root, "b.txt", b"two\n", "feat: second");
    let second = head(root);
    // `git tag` refuses this name; the ref can exist all the same.
    git(root, &["update-ref", "refs/tags/-x", second.as_str()]);
    let git_access = GitAccess::new(root, &SystemGit);

    let hazard = git(root, &["rev-parse", "refs/tags/a^"]);
    assert_ne!(hazard, second.as_str(), "the unguarded spelling reaches another commit");
    for name in ["a^", "a~1", "a@{1}", "a^{commit}", "a:b", "a..b", "-x^", "a b", ""] {
        assert_eq!(Rev::tag(name), None, "{name:?}");
        assert_eq!(Rev::branch(name), None, "{name:?}");
    }

    let dashed = Rev::tag("-x").expect("a legal ref name");
    assert_eq!(dashed.as_str(), "refs/tags/-x");
    assert_eq!(git_access.resolve_commit(&dashed).unwrap(), Some(second.clone()));
    assert!(git_access.commit_time(&dashed).unwrap() > 0);
    assert!(git_access.path_exists_at(&dashed, Path::new("b.txt")).unwrap());
    assert_eq!(
        git_access.read_at(&dashed, Path::new("b.txt")).unwrap().as_deref(),
        Some("two\n")
    );
    assert_eq!(
        git_access
            .files_containing_at(&dashed, "NEEDLE", &[crate::vcs::Pathspec::named_anywhere("a.txt")])
            .unwrap(),
        [PathBuf::from("a.txt")]
    );
    assert_eq!(summaries(root, Some(&dashed), &[]), Vec::<String>::new());
    assert_eq!(
        git_access.paths_differing_from(&Rev::tag("a").unwrap()).unwrap(),
        [PathBuf::from("b.txt")]
    );
    let dashed_branch = Rev::branch("-x").expect("a legal ref name");
    assert_eq!(git_access.resolve_commit(&dashed_branch).unwrap(), None);
    git(root, &["update-ref", "refs/heads/-x", second.as_str()]);
    assert_eq!(git_access.resolve_commit(&dashed_branch).unwrap(), Some(second));
}

/// A user-typed `--since` expression is read as revision syntax but never as a flag.
#[test]
fn a_typed_since_expression_is_never_read_as_a_flag() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    init_repo(root);
    commit_file(root, "a.txt", b"1\n", "feat: first");
    let first = head(root);
    commit_file(root, "b.txt", b"2\n", "feat: second");
    let git_access = GitAccess::new(root, &SystemGit);

    assert_eq!(git_access.merge_base_with_head("HEAD~1").unwrap(), Some(first));
    assert_eq!(git_access.merge_base_with_head("--help").unwrap(), None);
    assert_eq!(git_access.merge_base_with_head("--all").unwrap(), None);
    assert_eq!(git_access.merge_base_with_head("no-such-ref").unwrap(), None);
}

/// Paths named with `:`, `-`, a space, a newline or a glob character reach `add`, `rm --cached`, `check-ignore` and
/// `diff` as those paths and nothing else.
#[test]
fn literal_paths_with_odd_names_reach_add_check_ignore_and_diff_intact() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    init_repo(root);
    commit_file(root, ".gitignore", b"*.log\n", "chore: ignore logs");
    let odd = [":colon.txt", "-dash.txt", "sp ace.txt", "new\nline.txt", "star*.txt"];
    for name in odd.iter().chain(&["starX.txt"]) {
        std::fs::write(root.join(name), "1\n").unwrap();
    }
    let git_access = GitAccess::new(root, &SystemGit);
    let permit = ApplyPermit::force_for_tests();
    let paths: Vec<PathBuf> = odd.iter().map(PathBuf::from).collect();
    let literal: Vec<GitPath<'_>> = paths.iter().map(|path| GitPath::new(path)).collect();
    let indexed = || -> Vec<String> {
        git(root, &["ls-files", "-z"])
            .split('\0')
            .filter(|name| !name.is_empty())
            .map(str::to_owned)
            .collect()
    };

    git_access.stage(&literal, &permit).unwrap();
    let mut expected: Vec<String> = odd.iter().map(|name| (*name).to_owned()).collect();
    expected.push(".gitignore".to_owned());
    expected.sort();
    assert_eq!(indexed(), expected, "starX.txt must not ride along with star*.txt");
    git(root, &["commit", "-q", "-m", "feat: odd names"]);

    for name in odd {
        std::fs::write(root.join(name), "2\n").unwrap();
        let args = ["diff", "--name-only", "-z", "--", GitPath::new(Path::new(name)).pathspec().as_str()];
        let output = SystemGit.run("git", &args, root).unwrap();
        assert_eq!(output.stdout, format!("{name}\0"), "diff names exactly {name:?}");
    }
    let mut differing = git_access.paths_differing_from(&Rev::head()).unwrap();
    differing.sort();
    let mut changed: Vec<PathBuf> = paths.clone();
    changed.sort();
    assert_eq!(differing, changed);

    for (name, ignored) in [
        (":a.log", true),
        ("-b.log", true),
        ("sp c.log", true),
        ("new\nd.log", true),
        (":keep.txt", false),
        ("-keep.txt", false),
    ] {
        let arg = GitPath::new(Path::new(name)).check_ignore();
        let output = SystemGit.run("git", &["check-ignore", "--", &arg], root).unwrap();
        assert_eq!(output.exit_code, Some(if ignored { 0 } else { 1 }), "{name:?}");
    }

    git_access.stage_removal(&literal, &permit).unwrap();
    assert_eq!(indexed(), [".gitignore"]);
    assert!(paths.iter().all(|path| root.join(path).is_file()), "the files stay on disk");
}

